#include "test_common.h"
#include "hash_table.h"
static void test_numeric_hash(void){BmsHashTable_t t;int v=42;void*p=NULL;ASSERT_STATUS(BMS_STATUS_OK,HashTableInitialize(&t,5U,sizeof(int),BMS_HASH_KEY_UINT32));ASSERT_STATUS(BMS_STATUS_OK,HashTableInsertUint32(&t,1U,&v));ASSERT_STATUS(BMS_STATUS_OK,HashTableSearchUint32(&t,1U,&p));CU_ASSERT_EQUAL(*(int*)p,42);CU_ASSERT_EQUAL(HashTableGetCount(&t),1U);ASSERT_STATUS(BMS_STATUS_ALREADY_EXISTS,HashTableInsertUint32(&t,1U,&v));ASSERT_STATUS(BMS_STATUS_OK,HashTableDeleteUint32(&t,1U));ASSERT_STATUS(BMS_STATUS_NOT_FOUND,HashTableSearchUint32(&t,1U,&p));HashTableDeinitialize(&t);}
static void test_string_hash(void){BmsHashTable_t t;int v=7;void*p=NULL;ASSERT_STATUS(BMS_STATUS_OK,HashTableInitialize(&t,5U,sizeof(int),BMS_HASH_KEY_STRING));ASSERT_STATUS(BMS_STATUS_OK,HashTableInsertString(&t,"admin",&v));ASSERT_STATUS(BMS_STATUS_OK,HashTableSearchString(&t,"admin",&p));CU_ASSERT_EQUAL(*(int*)p,7);ASSERT_STATUS(BMS_STATUS_OK,HashTableDeleteString(&t,"admin"));HashTableDeinitialize(&t);}
void RegisterHashTableTests(void){CU_pSuite s=CU_add_suite("Hash Table",NULL,NULL);CU_add_test(s,"numeric key",test_numeric_hash);CU_add_test(s,"string key",test_string_hash);}
